-- ============================================================
-- 20261001 — Landing Page CMS (platform owner editable content)
--
-- `landing_page_content` stores per-section JSON overrides for the
-- public landing page (/). Section keys map to landingCopy keys:
--   hero → hero, features → features, for_doctors → forDoctors,
--   how_it_works → howItWorks, compare → compare, faq → faq,
--   urgency_bar → urgencyBar, plus new sections: testimonials,
--   seo (metadata), colors (CTA accent overrides).
--
-- RLS is enabled with NO policies → direct table access is denied
-- for everyone; reads/writes go exclusively through the service-role
-- client inside `lib/services/landingContent.ts` (server-only, after
-- `requirePlatformAdmin` for mutations).
--
-- ROLLBACK:
--   DROP TABLE IF EXISTS landing_page_content;
-- ============================================================

CREATE TABLE IF NOT EXISTS public.landing_page_content (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    section_key TEXT NOT NULL UNIQUE,
    content JSONB NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by UUID REFERENCES auth.users(id)
);

ALTER TABLE public.landing_page_content ENABLE ROW LEVEL SECURITY;

-- ============================================================
-- SEED — current static copy from lib/landing/landing-copy.ts so the
-- CMS starts with exactly what is live today (no visual change).
-- ============================================================
