('for_doctors', '{"eyebrow":"مش بنقدملك موقع إلكتروني للعيادة —","title":"بنحوّل موقعك لموظف استقبال رقمي شغال 24 ساعة","points":[{"icon":"🤖","title":"موظفة استقبال شغالة 24/7","desc":"ما بتحتاج تكون متاح ترد على \"كيف أحجز؟\"، \"شو خدماتكم؟\"، \"متى الدوام؟\" — المريض بيحكي مع المساعد بأي وقت."},{"icon":"💬","title":"بتفهم مشكلة المريض، مش بس قائمة خدمات","desc":"حوار طبيعي بيجمع معلومات حقيقية قبل ما المريض يوصل العيادة.","quote":"مثال: \"طاحونتي بتوجعني\" — بيجمع شو نوع الألم ومتى بدأ قبل ما يرشح."},{"icon":"📍","title":"بتوجّه المريض للطبيب المناسب","desc":"لو المريض داخل من QR Code خاص بعيادتك، بيضل المساعد شغال جوا عيادتك بس."},{"icon":"📅","title":"زيادة الحجوزات الفعلية","desc":"بدل \"اتصل فينا\"، بيصير \"ممتاز، بدك أحجزلك موعد؟\""},{"icon":"⚡","title":"تخفيف الضغط عن موظف الاستقبال","desc":"الأسئلة المتكررة بيردها الذكاء الاصطناعي."},{"icon":"🔳","title":"QR Code داخل العيادة","desc":"بالاستقبال، غرفة الانتظار، بطاقة المريض، الفاتورة."},{"icon":"📋","title":"جمع معلومات المريض قبل الموعد","desc":"مكان الألم، مدته، شدته، الأعراض — مع تنويه أن النظام ما بيشخّص بدل الطبيب."},{"icon":"⏰","title":"تذكير تلقائي بالمواعيد","desc":"تقليل مشكلة \"حجز موعد وما إجا\"."},{"icon":"🔄","title":"إعادة جدولة ذكية","desc":"المريض بيلاقي موعد بديل لحاله بدون تدخل يدوي."},{"icon":"📊","title":"تحليلات حقيقية عن مصدر المرضى","desc":"كم دخل، كم بدأ محادثة، كم حجز، كم ألغى."}],"cta":"اشترك وجرّبها بعيادتك"}'::jsonb),
